test_that("write_report writes one page per station", {
  res <- run_pipeline(nedap, verbose = 0)
  dir <- withr::local_tempdir()
  out <- write_report(res, dir, verbose = 0)
  expect_equal(basename(out), "index.html")
  html <- paste(readLines(out, encoding = "UTF-8"), collapse = "\n")
  locs <- sort(unique(res$fcr$per_pig$location))
  # overview + one page per station, every plot file exists
  expect_equal(lengths(regmatches(html, gregexpr("<section class=\"page\"", html))), length(locs) + 1L)
  imgs <- unique(regmatches(html, gregexpr("img/[^\"]+\\.png", html))[[1]])
  expect_length(imgs, 2L * length(locs))
  expect_true(all(file.exists(file.path(dir, imgs))))
  # every pig is in a table, removed pigs too, with a link from the search map
  for (p in c(res$fcr$per_pig$responder, res$removed$responder)) {
    expect_true(grepl(paste0("id=\"pig-", p, "\""), html, fixed = TRUE))
    expect_true(grepl(paste0("\"", p, "\":"), html, fixed = TRUE))
  }
  expect_true(grepl("removed", html, fixed = TRUE))
  # one station only
  one <- write_report(res, withr::local_tempdir(), locations = locs[1], verbose = 0)
  h1 <- paste(readLines(one, encoding = "UTF-8"), collapse = "\n")
  expect_equal(lengths(regmatches(h1, gregexpr("<section class=\"page\"", h1))), 2L)
  expect_error(write_report(list(), dir), "run_pipeline")
  expect_error(write_report(res, dir, locations = "nope", verbose = 0), "No station")
})

test_that("html helpers escape and format", {
  expect_equal(html_esc("a<b & \"c\""), "a&lt;b &amp; &quot;c&quot;")
  expect_equal(html_num(c(1234.5, NA), 0), c("1,234", ""))
  expect_equal(html_ms(c(1, 3)), "2 &plusmn; 1")
  expect_equal(html_ms(NA), "&ndash;")
})
